<?php
require_once __DIR__ . '/includes/config.php';
$id=(int)($_GET['id']??0); $stmt=db()->prepare("SELECT p.*, ROUND(COALESCE(AVG(r.stars),0),1) rating, COUNT(r.id) rating_count FROM playlists p LEFT JOIN ratings r ON r.playlist_id=p.id WHERE p.id=? GROUP BY p.id");$stmt->execute([$id]);$playlist=$stmt->fetch(); if(!$playlist){http_response_code(404);exit('Плейлист не найден.');}
if($_SERVER['REQUEST_METHOD']==='POST'){require_login();verify_csrf();$stars=(int)($_POST['stars']??0);if($stars>=1&&$stars<=5){$q=db()->prepare('INSERT INTO ratings(user_id,playlist_id,stars) VALUES(?,?,?) ON DUPLICATE KEY UPDATE stars=VALUES(stars)');$q->execute([user()['id'],$id,$stars]);}redirect('/playlist.php?id='.$id);}
db()->prepare('UPDATE playlists SET views=views+1 WHERE id=?')->execute([$id]);$playlist['views']++;
$userRating=null;if(logged_in()){$q=db()->prepare('SELECT stars FROM ratings WHERE user_id=? AND playlist_id=?');$q->execute([user()['id'],$id]);$userRating=$q->fetchColumn();}
$title=$playlist['title'].' · '.APP_NAME;require __DIR__.'/includes/header.php'; ?>
<section class="detail"><img class="detail-poster" src="<?=e($playlist['poster_url'])?>" alt="<?=e($playlist['title'])?>"><div class="detail-info"><span class="badge <?=strtolower($playlist['category'])?>"><?=e($playlist['category'])?></span><p class="eyebrow">ПЛЕЙЛИСТ #<?=$playlist['id']?></p><h1><?=e($playlist['title'])?></h1><div class="meta large"><span class="stars">★ <?=$playlist['rating'] ?: 'Нет оценок'?></span><span><?=$playlist['rating_count']?> оценок</span><span>◉ <?=number_format($playlist['views'],0,'',' ')?> просмотров</span></div><p class="description"><?=nl2br(e($playlist['description']))?></p><?php if(logged_in()):?><div class="actions"><a class="button" href="/download.php?id=<?=$playlist['id']?>">Получить ссылку</a><?php if($playlist['file_path']):?><a class="button ghost" href="/download.php?id=<?=$playlist['id']?>&file=1">Скачать файл</a><?php endif;?></div><form class="rating" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><span>Ваша оценка:</span><?php for($i=1;$i<=5;$i++):?><button name="stars" value="<?=$i?>" class="star <?=($userRating!==null&&$i<=$userRating)?'chosen':''?>" aria-label="<?=$i?> звезд">★</button><?php endfor;?></form><?php else:?><div class="login-gate"><strong>Хотите получить доступ?</strong><span>Войдите или зарегистрируйтесь, чтобы оценивать и получать плейлист.</span><a href="/login.php?next=<?=urlencode('/playlist.php?id='.$id)?>">Войти</a></div><?php endif;?></div></section><?php require __DIR__.'/includes/footer.php'; ?>
